MODULE_SOURCE='from __future__ import annotations\nfrom dataclasses import dataclass\nfrom pathlib import Path\nimport os,shutil,subprocess\nREAD_ONLY=True; PROBABILITY_ENABLED=False; DIRECTION_ENABLED=False; PUBLICATION_ALLOWED=False; EXECUTION_AUTHORITY=False\n@dataclass(frozen=True,slots=True)\nclass GMGNProviderAdmission:\n cli_path:str|None; config_ok:bool; version_ok:bool; admitted:bool; version_text:str|None=None; execution_authority:bool=False\nclass GMGNProviderError(RuntimeError): pass\nclass GMGNRateLimitError(GMGNProviderError):\n def __init__(self,message,retry_after_seconds=300.0): super().__init__(str(message)); self.retry_after_seconds=float(retry_after_seconds)\ndef _candidates():\n a=[]\n for n in ("gmgn-cli","gmgn-cli.cmd"):\n  x=shutil.which(n)\n  if x:a.append(Path(x))\n for base in (os.environ.get("APPDATA"),os.path.join(os.environ.get("USERPROFILE",""),"AppData","Roaming")):\n  if base:a.extend((Path(base)/"npm"/"gmgn-cli.cmd",Path(base)/"npm"/"gmgn-cli"))\n seen=set()\n for p in a:\n  q=os.path.normcase(os.path.normpath(str(p.expanduser().resolve())))\n  if q not in seen: seen.add(q); yield Path(q)\ndef locate_gmgn_cli():\n for p in _candidates():\n  if p.is_file():return str(p)\n return None\ndef _command(cli,args):\n cli=str(cli)\n if os.name=="nt" and Path(cli).suffix.lower() in (".cmd",".bat"):\n  c=os.environ.get("COMSPEC") or os.path.join(os.environ.get("SystemRoot",r"C:\\Windows"),"System32","cmd.exe")\n  return [c,"/d","/s","/c",subprocess.list2cmdline([cli,*map(str,args)])]\n return [cli,*map(str,args)]\ndef run_gmgn_cli(cli,args,timeout_seconds=30.0,text=True): return subprocess.run(_command(cli,args),capture_output=True,text=text,timeout=float(timeout_seconds),check=False)\ndef evaluate_gmgn_provider(timeout_seconds=10.0):\n cli=locate_gmgn_cli()\n if not cli:return GMGNProviderAdmission(None,False,False,False,None,False)\n try:\n  v=run_gmgn_cli(cli,["--version"],timeout_seconds,True); vt=(v.stdout or v.stderr or "").strip(); vok=v.returncode==0 and bool(vt)\n except Exception:vt=None;vok=False\n try:c=run_gmgn_cli(cli,["config","--check"],timeout_seconds,True);cok=c.returncode==0\n except Exception:cok=False\n return GMGNProviderAdmission(cli,cok,vok,bool(cli and cok and vok),vt,False)\ndef require_gmgn_provider(timeout_seconds=10.0):\n a=evaluate_gmgn_provider(timeout_seconds)\n if not a.cli_path:raise GMGNProviderError("GMGN_NOT_ADMITTED: cli not found")\n if not a.version_ok:raise GMGNProviderError("GMGN_NOT_ADMITTED: version check failed")\n if not a.config_ok:raise GMGNProviderError("GMGN_NOT_ADMITTED: config check failed")\n return a\n'
